import type { SwitchProps } from "./switch.types";

import * as RadixSwitch from "@radix-ui/react-switch";
import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { CheckSolid as DefaultCheckIcon, Close as DefaultCloseIcon } from "@exp-textura/icons";

import { SwitchClasses, StyledSwitch } from "./switch.styles";

const SwitchRoot = forwardRef<HTMLButtonElement, SwitchProps>(
  (
    { className, variant = "default", children, ...props }: SwitchProps,
    ref: React.ForwardedRef<HTMLButtonElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(SwitchClasses.root, className);

    return (
      <StyledSwitch
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        <span className={SwitchClasses.track} />
        <RadixSwitch.Thumb className={SwitchClasses.thumb} />
        {children}
      </StyledSwitch>
    );
  },
);

SwitchRoot.displayName = "Switch";

const OnIcon: React.FC<
  React.HTMLAttributes<HTMLOrSVGElement> & { children?: React.ReactElement }
> = ({ children, className, style }) => {
  const onIconClasses = clsx(SwitchClasses.onIcon, className);

  if (children && React.isValidElement(children)) {
    return React.cloneElement(children as React.ReactElement, {
      className: clsx(onIconClasses, children.props.className),
      style: { ...style, ...children.props.style },
    });
  }

  return <DefaultCheckIcon className={onIconClasses} style={style} />;
};

OnIcon.displayName = "Switch.OnIcon";

const OffIcon: React.FC<
  React.HTMLAttributes<HTMLOrSVGElement> & { children?: React.ReactElement }
> = ({ children, className, style }) => {
  const offIconClasses = clsx(SwitchClasses.offIcon, className);

  if (children && React.isValidElement(children)) {
    return React.cloneElement(children as React.ReactElement, {
      className: clsx(offIconClasses, children.props.className),
      style: { ...style, ...children.props.style },
    });
  }

  return <DefaultCloseIcon className={offIconClasses} style={style} />;
};

OffIcon.displayName = "Switch.OffIcon";

const Switch = Object.assign(SwitchRoot, {
  OnIcon,
  OffIcon,
});

export default Switch;
